import java.util.Scanner;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        String s = sc.next();

        // Split into segments: outside and inside parentheses
        String[] outsideParts = s.split("[()]");
        int maxOutside = 0;
        int insideCount = 0;

        for (int i = 0; i < outsideParts.length; i++) {
            String part = outsideParts[i];
            if (i % 2 == 0) { // outside parentheses
                String[] words = part.split("_");
                for (String w : words) {
                    if (!w.isEmpty()) {
                        maxOutside = Math.max(maxOutside, w.length());
                    }
                }
            } else { // inside parentheses
                String[] words = part.split("_");
                for (String w : words) {
                    if (!w.isEmpty()) {
                        insideCount++;
                    }
                }
            }
        }
        System.out.println(maxOutside + " " + insideCount);
    }
}
